                <div className={Style1.logo}>
                    <img src="logo1.webp" width="50px" height="50px"/></div>    
                    <div className={Style1.nav_items}>
                        <div className={Style1.option1} onClick={() => navigate('')}>Add students</div><div className={Style1.option2}  onClick={() => navigate('')}>  Add results</div>                        <div className={Style1.option1} onClick={() => navigate('')} >Edit  Results</div>                        <div className={Style1.option1} onClick={() => navigate('')}>ADD/Delete students</div> <div className={Style1.option1} onClick={() => navigate('')}>logout</div></div>  </div>      </div>
              </>    );   
